import * as THREE from 'three/webgpu';
import { texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load texture via cached loader
  const tex = ctx.textureLoader.load(config.assets.imageUrl);

  // Create plane geometry with aspect ratio matching image (512:320 = 1.6:1)
  const geometry = new THREE.PlaneGeometry(1.6, 1.0);

  // Create material with textured surface
  const material = new THREE.MeshBasicNodeMaterial({
    colorNode: texture(tex),
  });

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Apply scene placement from config
  mesh.position.set(
    config.scenePosition[0],
    config.scenePosition[1],
    config.scenePosition[2]
  );
  mesh.rotation.set(
    config.rotation[0],
    config.rotation[1],
    config.rotation[2]
  );
  mesh.scale.set(
    config.scale[0],
    config.scale[1],
    config.scale[2]
  );

  group.add(mesh);

  // Resource cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    tex.dispose();
  };

  // Event handlers (empty for static element)
  group.userData.handlers = {};

  return group;
}
